61	    /**
62	     * Add a claim for a person on the sheet; with no date it is dated the sheet's entry date
63	     * while one is set, else the sheet's today. One dated in a
64	     * soft-closed period is a late entry, audited as LATE_ENTRY after its CLAIM_ADDED. Refused when
65	     * it is dated inside a closed period, or when it is a correction that does not name a SETTLED claim
66	     * of the same person (see {@link #refuseUnlessCorrects}).
67	     */
68	    @Transactional
69	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
70	            String corrects) {
71	        Rollups.Rollup before = rollups.take(sheetId);
72	        Person person = person(sheetId, personId);
73	        LocalDate dated = date != null ? date : sheets.load(sheetId).defaultClaimDate();
74	        LocalDate dueBy = dueBy(sheets.lock(sheetId), person, dated);
75	        periods.refuseIfClosed(sheetId, dated);
76	        refuseIfRetired(person, dated);
