92	    /**
93	     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
94	     * edited: an OPEN one is changed by voiding it and adding a new one. Refused when the claim, or the
95	     * date it moves to, is inside a closed period, or when it would be a correction that does not name a
96	     * SETTLED claim of the same person.
97	     */
98	    @Transactional
99	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
100	            String corrects) {
101	        Rollups.Rollup before = rollups.take(sheetId);
102	        sheets.lock(sheetId);
103	        Claim claim = claim(sheetId, claimId);
104	        refuseUnlessEditable(sheetId, user, claim);
105	        if (date != null) {
106	            periods.refuseIfClosed(sheetId, date);
107	            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
108	        }
109	        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects);
110	        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
111	        claim.lockFor(null);
