118	    /**
119	     * Open a claim's editor for the user: the claim is locked for every other user until the editor is
120	     * saved or cancelled, or the sheet's today changes. Refused, taking no lock, when the claim cannot
121	     * be edited (see {@link #edit}) or another user's editor holds it.
122	     */
123	    @Transactional
124	    public Claim lock(String sheetId, String user, long claimId) {
125	        sheets.lock(sheetId);
126	        Claim claim = claim(sheetId, claimId);
127	        refuseUnlessEditable(sheetId, user, claim);
128	        claim.lockFor(user);
129	        return claims.saveAndFlush(claim);
