132	    /** Cancel the user's editor of a claim, releasing its lock; a lock another user holds is left as it is. */
133	    @Transactional
134	    public Claim unlock(String sheetId, String user, long claimId) {
135	        sheets.lock(sheetId);
136	        Claim claim = claim(sheetId, claimId);
137	        if (user.equals(claim.getLockedBy())) {
138	            claim.lockFor(null);
139	            claim = claims.saveAndFlush(claim);
140	        }
141	        return claim;
