150	    /**
151	     * Refuse an edit of a claim that is not a DRAFT, that is dated inside a closed period, or that
152	     * another user's editor holds (423).
153	     */
154	    private void refuseUnlessEditable(String sheetId, String user, Claim claim) {
155	        if (claim.getStatus() != ClaimStatus.DRAFT) {
156	            throw new ResponseStatusException(HttpStatus.CONFLICT,
157	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
158	        }
159	        periods.refuseIfClosed(sheetId, claim.getDate());
160	        if (claim.isLockedAgainst(user)) {
161	            throw new ResponseStatusException(HttpStatus.LOCKED,
162	                    "The claim is being edited by " + claim.getLockedBy() + ".");
163	        }
164	    }
