166	    /**
167	     * Move a claim to a new status, recording the event; refused (and nothing written) when the
168	     * claim's current status does not allow the move. Settling fixes the claim's due at the rate
169	     * the person's grade has in force on the claim's date, or at the figure a statement bound it to,
170	     * with the late charge it has then frozen in.
171	     * Opening numbers the claim and records who opened it; a voided claim keeps its number, which
172	     * is never reused. The user who opened a claim
173	     * is refused when settling it. A clerk settling a claim whose due is above the sheet's clerk limit
174	     * (a due of n/a is within any limit) sends it PENDING instead, for a steward to approve or reject;
175	     * a steward settles any. A move the sheet's permission matrix does not allow the user's role is
176	     * refused. A claim dated inside a closed period cannot be moved, nor can a claim
177	     * deferred on the sheet's today be settled. A SETTLED claim is voided only by a steward, within
178	     * {@link ClaimStatus#VOID_SETTLED_DAYS} days of its settlement; its frozen figure leaves every
179	     * total and the audit records it as reversed.
180	     */
181	    @Transactional
182	    public Claim move(String sheetId, String user, long claimId, ClaimStatus next) {
183	        // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
184	        // sheet are serialised: each sees the other's committed claim and number.
185	        LocalDate today = sheets.lock(sheetId).getToday();
186	        Rollups.Rollup before = rollups.take(sheetId);
187	        Claim claim = claim(sheetId, claimId);
188	        periods.refuseIfClosed(sheetId, claim.getDate());
189	        String action = switch (next) {
190	            case OPEN -> "open";
191	            case SETTLED -> "settle";
192	            case VOID -> "void";
193	            case PENDING, DRAFT -> throw new IllegalArgumentException("No move to " + next + ".");
194	        };
195	        if (!roles.permits(sheetId, user, action)) {
196	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
197	        }
198	        if (!claim.getStatus().canBecome(next)) {
199	            throw new ResponseStatusException(HttpStatus.CONFLICT,
200	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
201	        }
202	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
203	        if (voidingSettled) {
204	            refuseVoidingSettled(sheetId, user, claim, today);
205	        }
206	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
207	            throw new ResponseStatusException(HttpStatus.CONFLICT,
208	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
209	        }
210	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
211	            throw new ResponseStatusException(HttpStatus.CONFLICT,
212	                    "The user who opened a claim cannot settle it.");
213	        }
214	        Person person = person(sheetId, claim.getPersonId());
215	        BigDecimal settledDue = next == ClaimStatus.SETTLED
216	                ? dues.settling(claim, person.gradeOn(claim.getDate()))
217	                : null;
218	        if (next == ClaimStatus.OPEN) {
219	            refuseUnnoted(sheetId, claim, dues.due(claim, person.gradeOn(claim.getDate())));
220	        }
221	        if (next == ClaimStatus.SETTLED) {
222	            refuseUnproved(sheetId, claim, settledDue);
223	        }
224	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settledDue)) {
225	            next = ClaimStatus.PENDING;
226	            settledDue = null;
227	        }
228	        claim.become(next);
229	        if (next == ClaimStatus.OPEN) {
230	            claim.number(periods.nextClaimNumber(sheetId, claim.getDate()));
231	            claim.openedBy(user);
232	        }
233	        if (next == ClaimStatus.SETTLED) {
234	            claim.settleDue(settledDue);
235	        }
236	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
237	        String event = switch (next) {
238	            case OPEN -> "CLAIM_OPENED";
239	            case SETTLED -> "CLAIM_SETTLED";
240	            case PENDING -> "CLAIM_PENDING";
241	            case VOID -> "CLAIM_VOIDED";
242	            case DRAFT -> throw new IllegalStateException();
243	        };
244	        String suffix = next == ClaimStatus.SETTLED
245	                ? " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
246	                : voidingSettled
247	                ? " reversed=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE)
248	                : "";
249	        audited(event, sheetId, user, person, saved, saved.getNumber(), suffix);
250	        if (next == ClaimStatus.SETTLED) {
251	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
252	        }
253	        rollups.audit(sheetId, user, before);
254	        return saved;
255	    }
