273	    /**
274	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it,
275	     * the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
276	     * statement. Refused when the claim is not OPEN, when the date is not after the sheet's today, or
277	     * when the claim is dated inside a closed period.
278	     */
279	    @Transactional
280	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
281	        LocalDate today = sheets.lock(sheetId).getToday();
282	        Rollups.Rollup before = rollups.take(sheetId);
283	        Claim claim = claim(sheetId, claimId);
284	        if (claim.getStatus() != ClaimStatus.OPEN) {
285	            throw new ResponseStatusException(HttpStatus.CONFLICT,
286	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
287	        }
288	        if (!until.isAfter(today)) {
289	            throw new ResponseStatusException(HttpStatus.CONFLICT,
290	                    "A claim can only be deferred to a date after the sheet's today, " + today + ".");
291	        }
292	        periods.refuseIfClosed(sheetId, claim.getDate());
293	        claim.defer(until);
294	        Claim saved = claims.saveAndFlush(claim);
295	        audited("CLAIM_DEFERRED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
296	                " until=" + until);
297	        rollups.audit(sheetId, user, before);
298	        return saved;
