301	    /**
302	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at this moment at its live figure with
303	     * the late charge it has then. Only a steward approves, and not the user who opened the claim.
304	     */
305	    @Transactional
306	    public Claim approve(String sheetId, String user, long claimId) {
307	        sheets.lock(sheetId);
308	        Rollups.Rollup before = rollups.take(sheetId);
309	        Claim claim = pending(sheetId, user, claimId);
310	        if (user.equals(claim.getOpenedBy())) {
311	            throw new ResponseStatusException(HttpStatus.CONFLICT,
312	                    "The user who opened a claim cannot approve it.");
313	        }
314	        Person person = person(sheetId, claim.getPersonId());
315	        BigDecimal approvedDue = dues.approving(claim, person.gradeOn(claim.getDate()));
316	        refuseUnproved(sheetId, claim, approvedDue);
317	        claim.settleDue(approvedDue);
318	        claim.become(ClaimStatus.SETTLED);
319	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
320	        audited("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(),
321	                " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
322	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
323	        rollups.audit(sheetId, user, before);
324	        return saved;
325	    }
