327	    /**
328	     * Re-settle a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
329	     * claim bound by no statement (today's rates, grades, floor and late charge). Only a steward
330	     * re-settles; refused when the claim is not SETTLED or is dated inside a closed period.
331	     */
332	    @Transactional
333	    public Claim resettle(String sheetId, String user, long claimId) {
334	        sheets.lock(sheetId);
335	        Rollups.Rollup before = rollups.take(sheetId);
336	        Claim claim = claim(sheetId, claimId);
337	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
338	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
339	        }
340	        if (claim.getStatus() != ClaimStatus.SETTLED) {
341	            throw new ResponseStatusException(HttpStatus.CONFLICT,
342	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
343	        }
344	        periods.refuseIfClosed(sheetId, claim.getDate());
345	        Person person = person(sheetId, claim.getPersonId());
346	        BigDecimal old = claim.getSettledDue();
347	        claim.settleDue(dues.resettling(claim, person.gradeOn(claim.getDate())));
348	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
349	        audited("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
350	                " old=" + (old != null ? old.toPlainString() : NO_RATE)
351	                        + " new=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
352	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
353	        rollups.audit(sheetId, user, before);
354	        return saved;
355	    }
