357	    /**
358	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by its person's last
359	     * statement when that statement included it. Only a steward rejects.
360	     */
361	    @Transactional
362	    public Claim reject(String sheetId, String user, long claimId, String reason) {
363	        sheets.lock(sheetId);
364	        Rollups.Rollup before = rollups.take(sheetId);
365	        Claim claim = pending(sheetId, user, claimId);
366	        claim.become(ClaimStatus.OPEN);
367	        Claim saved = logged(claims.saveAndFlush(claim), user, person(sheetId, claim.getPersonId()));
368	        audited("CLAIM_REJECTED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
369	                " reason=" + reason.trim());
370	        rollups.audit(sheetId, user, before);
371	        return saved;
372	    }
