374	    /**
375	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its number and
376	     * date, and loses any figure a statement bound it to, its due live again until its new person's
377	     * next statement. Only a role the sheet's permission matrix allows (a steward by
378	     * default) reassigns. Refused when the claim is SETTLED or VOID, when it is
379	     * dated inside a closed period, when the new person is its own, is retired before its date, or (for
380	     * a correction) has no SETTLED claim of the number it corrects.
381	     */
382	    @Transactional
383	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
384	        sheets.lock(sheetId);
385	        Rollups.Rollup before = rollups.take(sheetId);
386	        Claim claim = claim(sheetId, claimId);
387	        if (!roles.permits(sheetId, user, "reassign")) {
388	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim.");
389	        }
390	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
391	            throw new ResponseStatusException(HttpStatus.CONFLICT,
392	                    "A " + claim.getStatus() + " claim cannot be reassigned.");
393	        }
394	        periods.refuseIfClosed(sheetId, claim.getDate());
395	        Person from = person(sheetId, claim.getPersonId());
396	        Person to = person(sheetId, personId);
397	        if (from.getId().equals(to.getId())) {
398	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
399	        }
400	        refuseIfRetired(to, claim.getDate());
401	        refuseUnlessCorrects(sheetId, personId, claim.getAmount(), claim.getCorrects());
402	        claim.reassign(to.getId());
403	        claim.unbind();
404	        Claim saved = claims.saveAndFlush(claim);
405	        audited("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
406	                " from=" + from.getName() + " to=" + to.getName());
407	        rollups.audit(sheetId, user, before);
408	        return saved;
409	    }
