411	    /**
412	     * Re-date an OPEN or PENDING claim: it keeps the due-by fixed when it was added and any figure a
413	     * statement bound it to, and belongs to the period its new date falls in. While the sheet numbers by
414	     * period and the claim's period changes, it takes the next number of its new period's sequence; its
415	     * old number is never given out again. Only a steward re-dates; refused when the claim is not OPEN
416	     * or PENDING, when its date or the new date is inside a closed period, or when the new date is after
417	     * its person's retirement.
418	     */
419	    @Transactional
420	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
421	        Sheet sheet = sheets.lock(sheetId);
422	        Rollups.Rollup before = rollups.take(sheetId);
423	        Claim claim = claim(sheetId, claimId);
424	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
425	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim.");
426	        }
427	        if (!claim.getStatus().isOpen()) {
428	            throw new ResponseStatusException(HttpStatus.CONFLICT,
429	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can.");
430	        }
431	        periods.refuseIfClosed(sheetId, claim.getDate());
432	        periods.refuseIfClosed(sheetId, date);
433	        Person person = person(sheetId, claim.getPersonId());
434	        refuseIfRetired(person, date);
435	        LocalDate old = claim.getDate();
436	        boolean moves = !Objects.equals(periods.periodOn(sheetId, old), periods.periodOn(sheetId, date));
437	        claim.redate(date);
438	        if (moves && sheet.numbersByPeriod()) {
439	            claim.number(periods.nextClaimNumber(sheetId, date));
440	        }
441	        Claim saved = claims.saveAndFlush(claim);
442	        audited("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
443	        rollups.audit(sheetId, user, before);
444	        return saved;
445	    }
446	
447	    /** What a split did: the original claim, as it is now, and the new claim split off it. */
448	    public record Split(Claim original, Claim split) {
449	    }
450	
451	    /**
452	     * Split an amount (above 0.00 and below the claim's amount) off an OPEN claim: it keeps the rest
453	     * of its amount and loses any figure a statement bound it to; a new OPEN claim with the split-off
454	     * amount, the same date and note, the next number, opened by the user and due by a date fixed now
455	     * from the terms in force on its date, names the original's number as the one it was split from.
456	     * Refused when the claim is not OPEN, is deferred on the sheet's today, or is dated inside a
457	     * closed period.
458	     */
459	    @Transactional
460	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
461	        Sheet sheet = sheets.lock(sheetId);
462	        LocalDate today = sheet.getToday();
463	        Rollups.Rollup before = rollups.take(sheetId);
464	        Claim claim = claim(sheetId, claimId);
465	        if (claim.getStatus() != ClaimStatus.OPEN) {
466	            throw new ResponseStatusException(HttpStatus.CONFLICT,
467	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
468	        }
469	        if (claim.isDeferredOn(today)) {
470	            throw new ResponseStatusException(HttpStatus.CONFLICT,
471	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be split.");
472	        }
473	        periods.refuseIfClosed(sheetId, claim.getDate());
474	        BigDecimal off = money(amount);
475	        if (off.signum() <= 0 || off.compareTo(claim.getAmount()) >= 0) {
476	            throw new ResponseStatusException(HttpStatus.CONFLICT,
477	                    "The amount split off must be above 0.00 and below the claim's " + claim.getAmount().toPlainString() + ".");
478	        }
479	        Person person = person(sheetId, claim.getPersonId());
480	        LocalDate dueBy = dueBy(sheet, person, claim.getDate());
481	        Claim split = claim.split(off, dueBy);
482	        split.number(periods.nextClaimNumber(sheetId, split.getDate()));
483	        split.openedBy(user);
484	        Claim original = claims.saveAndFlush(claim);
485	        split = logged(claims.saveAndFlush(split), user, person);
486	        audited("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
487	        audited("CLAIM_OPENED", sheetId, user, person, split);
488	        rollups.audit(sheetId, user, before);
489	        return new Split(original, split);
490	    }
491	
492	    /**
493	     * The PENDING claim a steward approves or rejects; refused when it is not PENDING, when its date
494	     * is inside a closed period, or when the user is not a steward.
495	     */
496	    private Claim pending(String sheetId, String user, long claimId) {
497	        Claim claim = claim(sheetId, claimId);
498	        periods.refuseIfClosed(sheetId, claim.getDate());
499	        if (claim.getStatus() != ClaimStatus.PENDING) {
500	            throw new ResponseStatusException(HttpStatus.CONFLICT,
501	                    "A " + claim.getStatus() + " claim is not pending approval.");
502	        }
503	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
504	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
505	        }
506	        return claim;
507	    }
508	
509	    /**
510	     * Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
511	     * in force on the claim's date (a due of n/a is within any threshold).
512	     */
513	    private void refuseUnproved(String sheetId, Claim claim, BigDecimal due) {
514	        BigDecimal threshold = sheets.load(sheetId).proofThresholdOn(claim.getDate());
515	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
516	            throw new ResponseStatusException(HttpStatus.CONFLICT,
517	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
518	                            + ": it needs a proof before it is settled.");
519	        }
520	    }
521	
522	    /**
523	     * Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
524	     * on the claim's date (a due of n/a is within any threshold).
525	     */
526	    private void refuseUnnoted(String sheetId, Claim claim, BigDecimal due) {
527	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
528	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
529	                && due.compareTo(threshold) > 0) {
530	            throw new ResponseStatusException(HttpStatus.CONFLICT,
531	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
532	                            + ": it needs a note before it is opened.");
533	        }
534	    }
535	
536	    /**
537	     * Refuse voiding a SETTLED claim unless the user acts as a steward and the sheet's today is no more
538	     * than {@link ClaimStatus#VOID_SETTLED_DAYS} days after the claim's settlement in its status log.
539	     */
540	    private void refuseVoidingSettled(String sheetId, String user, Claim claim, LocalDate today) {
541	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
542	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim.");
543	        }
544	        LocalDate settledOn = claim.settledOn();
545	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
546	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can only be voided within "
547	                    + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
548	        }
549	    }
550	
551	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit. */
552	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
553	        BigDecimal limit = sheets.clerkLimit(sheetId);
554	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
555	            return false;
556	        }
557	        return Role.CLERK.equals(roles.roleOf(sheetId, user));
558	    }
559	
560	    /**
561	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
562	     * same person; and refuse naming a claim to correct on any other claim.
563	     */
564	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
565	        if (amount.signum() >= 0) {
566	            if (corrects != null) {
567	                throw new ResponseStatusException(HttpStatus.CONFLICT,
568	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
569	            }
570	            return;
571	        }
572	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
573	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
574	                .isPresent();
575	        if (!settled) {
576	            throw new ResponseStatusException(HttpStatus.CONFLICT,
577	                    "A correction must name the number of a SETTLED claim of the same person.");
578	        }
579	    }
580	
581	    /** Refuse a claim dated after its person's retirement. */
582	    private static void refuseIfRetired(Person person, LocalDate date) {
583	        if (!person.canClaimOn(date)) {
584	            throw new ResponseStatusException(HttpStatus.CONFLICT,
585	                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
586	        }
587	    }
588	
589	    private Claim claim(String sheetId, long claimId) {
590	        return claims.findByIdAndSheetId(claimId, sheetId)
591	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
592	    }
593	
594	    /**
595	     * The date a claim of the person dated on a date is due by: its date plus the first of the
596	     * person's own terms, their grade's terms and the sheet's terms in force on it.
597	     */
598	    private static LocalDate dueBy(Sheet sheet, Person person, LocalDate date) {
599	        Integer own = person.getTerms();
600	        return date.plusDays(own != null ? own : sheet.termsFor(person.gradeOn(date), date));
601	    }
602	
603	    private Person person(String sheetId, long personId) {
604	        return people.findByIdAndSheetId(personId, sheetId)
605	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
606	    }
607	
608	    /**
609	     * Add a line to the claim's status log for the status it now has: by the user, on the sheet's
610	     * today, with its due as computed now.
611	     */
612	    private Claim logged(Claim claim, String user, Person person) {
613	        claim.logged(user, sheets.today(claim.getSheetId()), dues.due(claim, person.gradeOn(claim.getDate())));
614	        return claims.saveAndFlush(claim);
615	    }
616	
617	    /** Record the change to the claim once it is committed; a claim with a number carries it. */
618	    private void audited(String event, String sheetId, String user, Person person, Claim claim) {
619	        audited(event, sheetId, user, person, claim, claim.getNumber(), "");
620	    }
621	
622	    private void audited(String event, String sheetId, String user, Person person, Claim claim, String number,
623	            String suffix) {
624	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
625	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
626	                + (number != null ? " number=" + number : "") + suffix);
627	    }
628	
629	    /** The due figure a claim shows, without its late charge (see {@link Dues#figure}). */
630	    public BigDecimal figure(Claim claim, String grade) {
631	        return dues.figure(claim, grade);
632	    }
633	
634	    /** The due a claim shows, with its late charge (see {@link Dues#due}). */
635	    public BigDecimal due(Claim claim, String grade) {
636	        return dues.due(claim, grade);
637	    }
638	
639	    private static BigDecimal money(BigDecimal amount) {
640	        return amount.setScale(2, RoundingMode.UNNECESSARY);
641	    }
642	
643	    private static String clean(String note) {
644	        return note == null ? "" : note.trim();
